        language: 'python',
        code: 'import re\n\ndef chunk_sentences(text, max_words):\n    sentences = re.split(r"(?<=[.!?])\\s+", text.strip())\n    chunks, current = [], []\n    for sentence in sentences:\n        size_now = len(" ".join(current).split())\n        if current and size_now + len(sentence.split()) > max_words:\n            chunks.append(" ".join(current))\n            current = []\n        current.append(sentence)\n    if current:\n        chunks.append(" ".join(current))\n    return chunks\n\npolicy = ("Orders can be cancelled within 60 seconds of placing them. "\n          "After that, the restaurant may already be cooking. "\n          "UPI refunds usually arrive within 3 to 5 working days. "\n          "Wallet refunds are instant.")\nfor i, chunk in enumerate(chunk_sentences(policy, max_words=20)):\n    print(i, chunk)',
