        code: 'def chunk_words(text, size, overlap=0):\n    words = text.split()\n    step = size - overlap\n    chunks = []\n    for start in range(0, len(words), step):\n        chunks.append(" ".join(words[start:start + size]))\n        if start + size >= len(words):\n            break\n    return chunks\n\npolicy = ("Orders can be cancelled within 60 seconds of placing them. After that, the "\n          "restaurant may already be cooking. If an item is missing or damaged, report it "\n          "in the app within 2 hours of delivery. Refunds for prepaid orders go back to the "\n          "original payment method. UPI refunds usually arrive within 3 to 5 working days. "\n          "Wallet refunds are instant. Cash-on-delivery orders are refunded as wallet credit.")\n\n# Each test question comes with the exact passage that answers it.\nanswers = [\n    "Orders can be cancelled within 60 seconds of placing them.",\n    "report it in the app within 2 hours of delivery.",\n    "UPI refunds usually arrive within 3 to 5 working days.",\n    "Cash-on-delivery orders are refunded as wallet credit.",\n]\n\nfor size, overlap in [(8, 0), (8, 4), (16, 0), (16, 6), (32, 0)]:\n    chunks = chunk_words(policy, size, overlap)\n    kept = sum(any(a in c for c in chunks) for a in answers)\n    print(f"size={size:>2} overlap={overlap}  chunks={len(chunks):>2}  answers kept whole: {kept}/{len(answers)}")',
